               <input id="q1-html" type="checkbox" name="q1" value="HTML">
               <span>HTML</span>
             </label>
             <label class="choice" for="q1-go">
               <input id="q1-go" type="checkbox" name="q1" value="Go" data-correct="true">
               <span>Go</span>
             </label>
             <label class="choice" for="q1-javascript">
               <input id="q1-javascript" type="checkbox" name="q1" value="JavaScript" data-correct="true">
               <span>JavaScript</span>
             </label>
           </div>
         </fieldset>
       </div>

       <div class="form-field">
         <fieldset>
           <legend>2. Which of these are compiled languages?</legend>
           <div class="choices">
             <label class="choice" for="q2-python">
               <input id="q2-python" type="checkbox" name="q2" value="Python">
               <span>Python</span>
             </label>
             <label class="choice" for="q2-rust">
               <input id="q2-rust" type="checkbox" name="q2" value="Rust" data-correct="true">
               <span>Rust</span>
             </label>
             <label class="choice" for="q2-c">
               <input id="q2-c" type="checkbox" name="q2" value="C" data-correct="true">
               <span>C</span>
             </label>
             <label class="choice" for="q2-javascript">
               <input id="q2-javascript" type="checkbox" name="q2" value="JavaScript">
               <span>JavaScript</span>
             </label>
           </div>
         </fieldset>
       </div>

       <div class="form-field">
         <fieldset>
           <legend>3. Which of these are widely used on the web front end?</legend>
           <div class="choices">
             <label class="choice" for="q3-html">
               <input id="q3-html" type="checkbox" name="q3" value="HTML" data-correct="true">
               <span>HTML</span>
             </label>
             <label class="choice" for="q3-css">
               <input id="q3-css" type="checkbox" name="q3" value="CSS" data-correct="true">
               <span>CSS</span>
             </label>
             <label class="choice" for="q3-javascript">
               <input id="q3-javascript" type="checkbox" name="q3" value="JavaScript" data-correct="true">
               <span>JavaScript</span>
             </label>
             <label class="choice" for="q3-ruby">
               <input id="q3-ruby" type="checkbox" name="q3" value="Ruby">
               <span>Ruby</span>
             </label>
           </div>
         </fieldset>
       </div>

       <div class="actions">
         <button type="submit">Check answers</button>
         <p class="status" id="quiz-status" aria-live="polite" aria-atomic="true"></p>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById('quiz-form');
     const status = document.getElementById('quiz-status');

     const questions = [
       { name: 'q1' },
       { name: 'q2' },
       { name: 'q3' },
     ];

     function evaluateQuestion(questionName) {
       const inputs = Array.from(form.querySelectorAll(`input[name="${questionName}"]`));
       const selected = new Set(inputs.filter((input) => input.checked).map((input) => input.value));
       const correct = new Set(inputs.filter((input) => input.dataset.correct === 'true').map((input) => input.value));

       if (selected.size !== correct.size) {
         return false;
       }

       for (const value of correct) {
         if (!selected.has(value)) {
           return false;
         }
       }

       return true;
     }

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const score = questions.reduce((count, question) => count + (evaluateQuestion(question.name) ? 1 : 0), 0);
       const message = score === questions.length
         ? `Perfect score — ${score} of ${questions.length} correct.`
         : `You got ${score} of ${questions.length} correct.`;

       status.innerHTML = `<strong>${message}</strong>`;
       status.setAttribute('tabindex', '-1');
       status.focus();
     });
   </script>
